package io.spring.application.article;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoMoreInteractions;
import static org.mockito.Mockito.when;

import io.spring.application.ArticleQueryService;
import io.spring.application.data.ArticleData;
import io.spring.core.user.User;
import io.spring.infrastructure.mybatis.readservice.ArticleFavoritesReadService;
import io.spring.infrastructure.mybatis.readservice.ArticleReadService;
import io.spring.infrastructure.mybatis.readservice.UserRelationshipQueryService;
import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class ArticleQueryServiceTest {

    @Mock
    private ArticleReadService articleReadService;

    @Mock
    private UserRelationshipQueryService userRelationshipQueryService;

    @Mock
    private ArticleFavoritesReadService articleFavoritesReadService;

    @InjectMocks
    private ArticleQueryService articleQueryService;

    // GreyTest trace: findById | IF-1-TRUE | BR-002 -> TP-023 -> TC-1202
    @Test
    void findById_WhenArticleNotFound_ReturnsEmpty() {
        // Arrange
        User user = org.mockito.Mockito.mock(User.class);
        org.mockito.Mockito.when(user.getId()).thenReturn("user-1");
        when(articleReadService.findById("missing-article")).thenReturn(null);

        // Act
        Optional<ArticleData> result = articleQueryService.findById("missing-article", user);

        // Assert
        assertFalse(result.isPresent());
        verify(articleReadService).findById("missing-article");
        verifyNoMoreInteractions(articleFavoritesReadService, userRelationshipQueryService);
    }
}

